import React from "react";
import { useNavigate } from "react-router-dom";
import "./HomePage.css";

function HomePage() {
  const navigate = useNavigate();

  const menuItems = [
    { name: "Home", action: () => navigate("/") },
    { name: "Profile", action: () => navigate("/profile") },
    { name: "Bookings", action: () => navigate("/booking") },
    { name: "Payment", action: () => navigate("/payment") },
    { name: "Success", action: () => navigate("/success") },
  ];

  return (
    <div className="homepage-container">
      {/* Navbar */}
      <nav className="navbar">
        <div className="navbar-logo">Parking Slot System</div>
        <div className="navbar-links">
          {menuItems.map((item, index) => (
            <button key={index} className="nav-btn" onClick={item.action}>
              {item.name}
            </button>
          ))}
          <button
            className="logout-btn"
            onClick={() => {
              localStorage.removeItem("user");
              navigate("/login");
            }}
          >
            Logout
          </button>
        </div>
      </nav>

      {/* Sidebar */}
      <div className="sidebar">
        {menuItems.map((item, index) => (
          <button key={index} className="sidebar-btn" onClick={item.action}>
            {item.name}
          </button>
        ))}
      </div>

      {/* Main content */}
      <div className="main-content">
        <h1>Welcome to the Parking Slot Booking System</h1>
        <p>Select an option from the sidebar or navbar to get started.</p>
      </div>
    </div>
  );
}

export default HomePage;
